// Session is table sessions.
type Session struct {
	ID             [16]byte
	UserEmail      string
	Asset          *Asset
	AssetHostname  string
	Principal      string
	Protocol       string
	Origin         string
	OriginReason   *string
	State          string
	StartedAt      time.Time
	EndedAt        *time.Time
	ClientIP       string
	Fidelity       string
	RecordingBytes int64
	RecordingPath  *string
	CommandCount   *int32
	ExitCode       *int32
	ChainHead      *string
	RiskFlags      []string
	ReportedBy     string
	CreatedAt      time.Time
	RecordingKey   *string

	TerminatedBy      *string
	TerminationReason *string
	// EndInferred marks an end the control plane deduced rather than observed.
	//
	// True only for a session closed by CloseAbandonedSessions, whose EndedAt is
	// its last report rather than a reported end. Without this a closed session
	// with an end time reads as a clean logout and an auditor cannot tell the
	// two apart.
	EndInferred bool

	// LastReportedAt is when anything last said this session existed.
	//
	// A gateway killed rather than drained never reports the end, so `active`
	// alone cannot tell a session still running from one whose gateway is
	// gone -- fifteen in dev have been active since early September. Every
	// report stamps this and gateways re-report what they hold once a
	// minute, so silence becomes measurable instead of indistinguishable
	// from life.
	LastReportedAt time.Time
	// Kind is terminal or database; Database is set for the latter
	// (migration 026).
	Kind     string
	Database *Database
}

func (m *Session) Schema(t *storm.Table) {
	t.Col(&m.Asset).ConstraintName("sessions_asset_id_fkey")
	t.Col(&m.Asset).OnDelete(storm.SetNull)
	t.Col(&m.Protocol).Default("'ssh'::text")
	t.Col(&m.Origin).Default("'brokered'::text")
	t.Col(&m.State).Default("'active'::text")
	t.Col(&m.ClientIP).Default("''::text")
	t.Col(&m.Fidelity).Default("'pty'::text")
	t.Col(&m.RecordingBytes).Default("0")
	t.Col(&m.RiskFlags).Default("'{}'::text[]")
	t.Col(&m.ReportedBy).Default("''::text")
	t.Col(&m.CreatedAt).Default("now()")
	t.Col(&m.LastReportedAt).Default("now()")
	t.Col(&m.EndInferred).Default("false")
	t.Index(&m.Asset).Named("sessions_asset_id_idx")
	t.Index(storm.Desc(&m.StartedAt)).Where("origin = 'direct'::text").Named("sessions_direct_idx")
	t.Index(storm.Desc(&m.StartedAt)).Named("sessions_started_idx")
	t.Index(&m.State).Named("sessions_state_idx")
	t.Index(&m.TerminatedBy).Where("terminated_by IS NOT NULL").Named("sessions_terminated_idx")
	t.Col(&m.Kind).Default("'terminal'::text")
	t.Col(&m.Database).ConstraintName("sessions_database_id_fkey")
	t.Col(&m.Database).NoIndex()
}

// Database is table databases: a Postgres database on a server, opened
// through that server's agent (migration 026). Policy holds the safety limits
// the console writes; empty means every default.
type Database struct {
	ID         [16]byte
	Asset      Asset
	Engine     string
	Host       string
	Port       int32
	PoolerHost string
	PoolerPort int32
	ConfigPath string
	Dbname     string
	AdminUser  string
	Label      string
	Policy     storm.JSON
	CreatedBy  string
	CreatedAt  time.Time
}

func (m *Database) Schema(t *storm.Table) {
	t.Col(&m.PoolerHost).Default("''::text")
	t.Col(&m.PoolerPort).Default("0")
	t.Col(&m.ConfigPath).Default("''::text")
	t.Col(&m.ID).Default("gen_random_uuid()")
	t.Col(&m.Asset).ConstraintName("databases_asset_id_fkey")
	t.Col(&m.Asset).OnDelete(storm.Cascade)
	t.Col(&m.Engine).Default("'postgres'::text")
	t.Col(&m.Host).Default("'/var/run/postgresql'::text")
	t.Col(&m.Port).Default("5432")
	t.Col(&m.AdminUser).Default("'postgres'::text")
	t.Col(&m.Label).Default("'production'::text")
	t.Col(&m.Policy).Default("'{}'::jsonb")
	t.Col(&m.CreatedBy).Default("''::text")
	t.Col(&m.CreatedAt).Default("now()")
	t.UniqueNamed("databases_asset_id_port_dbname_key", &m.Asset, &m.Port, &m.Dbname)
	t.CheckNamed("databases_dbname_check", "(length(dbname) >= 1) AND (length(dbname) <= 63)")
	t.CheckNamed("databases_engine_check",
		"engine = ANY (ARRAY['postgres'::text, 'redis'::text, 'rabbitmq'::text, 'mysql'::text, 'mongodb'::text, 'kafka'::text])")
	t.CheckNamed("databases_label_check",
		"label = ANY (ARRAY['production'::text, 'staging'::text, 'development'::text])")
	t.CheckNamed("databases_port_check", "(port >= 1) AND (port <= 65535)")
	t.CheckNamed("databases_pooler_port_check", "(pooler_port >= 0) AND (pooler_port <= 65535)")
	t.Index(&m.Asset).Named("databases_asset_idx")
	t.Index(&m.Asset, &m.Port).Unique().Where("engine = 'redis'::text").Named("databases_redis_server_key")
}

// DatabaseAssignment is table database_assignments: who may open a database
