// User is table users.
type User struct {
	ID            [16]byte
	Email         string
	DisplayName   string
	Role          string
	MfaEnrolled   bool
	LastSeenAt    *time.Time
	CreatedAt     time.Time
	PasswordHash  *string
	TotpSecret    *string
	MfaEnrolledAt *time.Time
	DisabledAt    *time.Time
	// LoginName is the person's account on servers; SshPublicKey the key
	// they reach it directly with; DisabledBy who removed them.
	LoginName    *string
	SshPublicKey string
	DisabledBy   *string
	// SessionsValidAfter: a cookie issued before it is refused.
	// TotpPendingSecret: an enrolment not yet confirmed. TotpLastStep: the
	// last authenticator step accepted, so each code signs in once.
	SessionsValidAfter *time.Time
	TotpPendingSecret  *string
	TotpLastStep       *int64
	// HomeTenant is the organization holding this person's credentials when
	// they were shared in from another one; nil when they are this
	// organization's own. Shareable is whether another organization may add
	// them, set here by the organization they belong to.
	HomeTenant *string
	Shareable  bool
	// PasswordChangeRequired holds the account to "change your password"
	// while its password is a temporary one; PasswordExpiresAt is when that
	// temporary password stops working.
	PasswordChangeRequired bool
	PasswordExpiresAt      *time.Time
}

func (m *User) Schema(t *storm.Table) {
	t.Col(&m.ID).Default("gen_random_uuid()")
	t.Col(&m.Role).Default("'operator'::text")
	t.Col(&m.MfaEnrolled).Default("false")
	t.Col(&m.Shareable).Default("false")
	t.Col(&m.PasswordChangeRequired).Default("false")
	t.Col(&m.CreatedAt).Default("now()")
	t.UniqueNamed("users_email_key", &m.Email)
	t.Index(storm.Lower(&m.Email)).Unique().Named("users_email_lower_key")
	t.Col(&m.SshPublicKey).Default("''::text")
	t.Index(&m.LoginName).Unique().Where("login_name IS NOT NULL").Named("users_login_name_key")
	t.CheckNamed("users_login_name_check",
		"(login_name IS NULL) OR (login_name ~ '^[a-z_][a-z0-9._-]{0,31}$'::text)")
}

